def transform(g):
    H,W=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for row in g for x in row)
    sep=None
    for i,row in enumerate(g):
        if len(set(row))==1 and cnt[row[0]]==W:
            sep=('r',i); break
    if sep is None:
        for j in range(W):
            col=[g[i][j] for i in range(H)]
            if len(set(col))==1 and cnt[col[0]]==H:
                sep=('c',j); break
    kind,idx=sep
    if kind=='r':
        A=[r[:] for r in g[:idx]]; B=[r[:] for r in g[idx+1:]]
    else:
        A=[r[:idx] for r in g]; B=[r[idx+1:] for r in g]
    s=(set(sum(A,[]))&set(sum(B,[]))).pop()
    return [[3 if (A[i][j]==s and B[i][j]==s) else s for j in range(len(A[0]))] for i in range(len(A))]

